#!/bin/bash
# Print the "OpenCCU-Base Changes" section of the release notes: the entries
# of the OpenCCU-Base component changelogs (src/<component>/CHANGELOG.md) that
# are new between two OpenCCU-Base revisions, as generated by
# scripts/changelog-sections.py of OpenCCU-Base. Nothing is printed if both
# revisions are equal, one of them is unknown or the OpenCCU-Base checkout
# does not have that script yet.
#
# Usage: scripts/openccu-base-changes.sh <openccu-base-dir> <old> <new> <limit>
#
#   <openccu-base-dir>  git checkout of OpenCCU-Base containing both revisions
#   <limit>             maximum length of the section in characters: components
#                       that do not fit are replaced by a link to their changelog
set -eo pipefail

BASE_DIR=$1
OLD=$2
NEW=$3
LIMIT=$4
URL="${GITHUB_SERVER_URL:-https://github.com}/OpenCCU/OpenCCU-Base"
SCRIPT=scripts/changelog-sections.py

if [[ -z "${OLD}" || -z "${NEW}" || "${OLD}" == "${NEW}" || ! -f "${BASE_DIR}/${SCRIPT}" ]]; then
  exit 0
fi

HEADING="## 🧩 OpenCCU-Base Changes:
<sub>For all changes, see the [full commit log](${URL}/compare/${OLD}...${NEW}).</sub>"
LIMIT=$((LIMIT - ${#HEADING}))
if [[ ${LIMIT} -lt 0 ]]; then
  LIMIT=0
fi

# drop the "## Component changes" heading of changelog-sections.py
COMPONENTS=$(cd "${BASE_DIR}" && python3 "${SCRIPT}" --limit "${LIMIT}" \
  --link-base "${URL}/blob/${NEW}" "${OLD}" "${NEW}" | tail -n +2)
if [[ -n "${COMPONENTS}" ]]; then
  printf '%s\n%s\n' "${HEADING}" "${COMPONENTS}"
fi
